orbital RiyaCurveOrbital {
  uses Motion from "std/behaviors/std-motion-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"

  type RiyaCurveBody = {
    id : string!
    x : number!
    y : number!
    vx : number
    vy : number
    ax : number
    ay : number
  }
  type RiyaCurveFeature = {
    id : string
    x : number!
    y : number!
    z : number
    type : string!
    color : string
    elevation : number
    done : boolean
  }
  type RiyaCurveFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
  }

  entity RiyaCurveState [runtime, shared] {
    id : string!
    active : boolean = false
    bodies : [RiyaCurveBody] = []
    gravity : number = 0
    biasAx : number = 0
    biasAy : number = 0
    features : [RiyaCurveFeature] = []
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaCurveFx] = []
    holding : number = 0
    celebrated : boolean = false
  }

  trait CurveMotion = Motion.traits.MotionBody -> RiyaCurveState {
    events {
      THRUST: CURVE_THRUST
      IMPULSE: CURVE_IMPULSE
      PLACE: CURVE_PLACE
      SET_GRAVITY: CURVE_SET_GRAVITY
      RESTART: CURVE_RESTART
      BODY_MOVED: CURVE_MOVED
    }
    config {
      running: true
      gravity: 0
      damping: 0.94
      maxSpeed: 7
      xMin: -6.4
      xMax: 6.4
      yMin: -6
      yMax: 4
      bodies: [ { id: "hero", x: -5, y: 0, vx: 0, vy: 0, ax: 0, ay: 0 } ]
    }

    listens {
      THRUST { id : string!, ax : number!, ay : number! }
      IMPULSE { id : string!, dvx : number!, dvy : number! }
      PLACE { id : string!, x : number!, y : number! }
      SET_GRAVITY { gravity : number! }
      SET_BIAS { biasAx : number!, biasAy : number! }
      RESTART { id : string }
      RiyaCurvePlay.CURVE_IMPULSE -> CURVE_IMPULSE
      RiyaCurvePlay.CURVE_RESTART -> CURVE_RESTART
      RiyaCurvePlay.CURVE_THRUST -> CURVE_THRUST
    }
  }

  trait CurveGate = Gate.traits.ObjectiveFlow -> RiyaCurveState {
    events {
      PROGRESS: CURVE_PROGRESS
      GAME_END: CURVE_GAME_END
      RESTART: CURVE_RESTART
    }
    config { running: true }

    listens {
      PROGRESS { objectivesLeft : number, movesLeft : number }
      RESTART { id : string }
      RiyaCurvePlay.CURVE_PROGRESS -> CURVE_PROGRESS
      RiyaCurvePlay.CURVE_RESTART -> CURVE_RESTART
    }
  }

  trait CurveFx = Particles.traits.FxParticles -> RiyaCurveState {
    events {
      BURST: CURVE_BURST
    }
    config { running: true }

    listens {
      BURST { particles : [Fx] }
      RESTART { }
      RiyaCurvePlay.CURVE_BURST -> CURVE_BURST
    }
  }

  trait RiyaCurvePlay -> @rebindable RiyaCurveState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.holding 0)
        (set @entity.celebrated false)
        (set @entity.features @config.stars)
        (set @entity.score 0)
        (set @entity.objectivesLeft (array/len @config.stars))
