          type: game-shell
          appName: "riya"
          hud: { type: game-hud, stats: [ { label: @config.objectiveText }, { label: "x", value: (math/round (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x) 1) }, { label: "f(x)", value: (math/round (- (* 0.25 (* (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x) (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) 4) 1) }, { label: "★", value: @entity.score } ] }
