            keyMap: { ArrowLeft: "CURVE_PUSH_LEFT", KeyA: "CURVE_PUSH_LEFT", ArrowRight: "CURVE_PUSH_RIGHT", KeyD: "CURVE_PUSH_RIGHT" }
