            curves: [ { label: "f(x) = 0.25x² − 4", color: "#94a3b8", samples: (array/map (array/range -64 65) (fn i (let ((xx (* @i 0.1))) { x: @xx, y: (- (* 0.25 (* @xx @xx)) 4) }))) } ]
            points: (array/concat
              (array/map @entity.features (fn f { x: (object/get @f x), y: (object/get @f y), label: "★", color: @config.starColor, radius: 9 }))
