      CURVE_PUSH_LEFT_UP -> idle when (== @entity.holding -1)
        (set @entity.holding 0)
        (emit CURVE_THRUST { id: "hero", ax: 0, ay: 0 })

      CURVE_PUSH_RIGHT_UP -> idle when (== @entity.holding 1)
        (set @entity.holding 0)
        (emit CURVE_THRUST { id: "hero", ax: 0, ay: 0 })

      CURVE_PAD_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit CURVE_IMPULSE { id: "hero", dvx: (- 0 @config.padImpulse), dvy: 0 })

      CURVE_PAD_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit CURVE_IMPULSE { id: "hero", dvx: @config.padImpulse, dvy: 0 })

