    }

    listens {
      CurveGate.CURVE_GAME_END -> CURVE_GAME_END
    }
  }

  page "/riya-curve" as RiyaCurvePage -> CurveMotion, CurveGate, CurveFx, RiyaCurvePlay
}


orbital RiyaSlopeOrbital {
  uses Motion from "std/behaviors/std-motion-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"

  type RiyaSlopeBody = {
    id : string!
    x : number!
    y : number!
    vx : number
    vy : number
    ax : number
    ay : number
  }
  type RiyaSlopeFeature = {
    id : string
    x : number!
    y : number!
    z : number
    type : string!
    color : string
    elevation : number
    done : boolean
  }
  type RiyaSlopeFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
  }

  entity RiyaSlopeState [runtime, shared] {
    id : string!
    active : boolean = false
    bodies : [RiyaSlopeBody] = []
    gravity : number = 0
    biasAx : number = 0
    biasAy : number = 0
    features : [RiyaSlopeFeature] = []
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaSlopeFx] = []
    holding : number = 0
    celebrated : boolean = false
  }

  trait SlopeMotion = Motion.traits.MotionBody -> RiyaSlopeState {
    events {
      THRUST: SLOPE_THRUST
      IMPULSE: SLOPE_IMPULSE
      PLACE: SLOPE_PLACE
      SET_GRAVITY: SLOPE_SET_GRAVITY
      SET_BIAS: SLOPE_BIAS
      RESTART: SLOPE_RESTART
      BODY_MOVED: SLOPE_MOVED
    }
    config {
      running: true
      gravity: 0
      damping: 0.97
      maxSpeed: 7
      xMin: -6.3
      xMax: 6.3
      yMin: -5
      yMax: 5
      bodies: [ { id: "hero", x: -5.5, y: 0, vx: 0, vy: 0, ax: 0, ay: 0 } ]
    }

    listens {
      THRUST { id : string!, ax : number!, ay : number! }
      IMPULSE { id : string!, dvx : number!, dvy : number! }
      PLACE { id : string!, x : number!, y : number! }
      SET_GRAVITY { gravity : number! }
      SET_BIAS { biasAx : number!, biasAy : number! }
      RESTART { id : string }
      RiyaSlopePlay.SLOPE_BIAS -> SLOPE_BIAS
      RiyaSlopePlay.SLOPE_IMPULSE -> SLOPE_IMPULSE
      RiyaSlopePlay.SLOPE_RESTART -> SLOPE_RESTART
      RiyaSlopePlay.SLOPE_THRUST -> SLOPE_THRUST
    }
  }

  trait SlopeGate = Gate.traits.ObjectiveFlow -> RiyaSlopeState {
    events {
      PROGRESS: SLOPE_PROGRESS
      GAME_END: SLOPE_GAME_END
      RESTART: SLOPE_RESTART
    }
    config { running: true }

    listens {
      PROGRESS { objectivesLeft : number, movesLeft : number }
      RESTART { id : string }
      RiyaSlopePlay.SLOPE_PROGRESS -> SLOPE_PROGRESS
      RiyaSlopePlay.SLOPE_RESTART -> SLOPE_RESTART
    }
  }

  trait SlopeFx = Particles.traits.FxParticles -> RiyaSlopeState {
    events {
      BURST: SLOPE_BURST
    }
    config { running: true }

    listens {
      BURST { particles : [Fx] }
      RESTART { }
      RiyaSlopePlay.SLOPE_BURST -> SLOPE_BURST
    }
  }

  trait RiyaSlopePlay -> @rebindable RiyaSlopeState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.holding 0)
        (set @entity.celebrated false)
        (set @entity.features @config.stars)
        (set @entity.score 0)
        (set @entity.objectivesLeft (array/len @config.stars))
        (emit SLOPE_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: "riya"
          hud: { type: game-hud, stats: [ { label: @config.objectiveText }, { label: "x", value: (math/round (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x) 1) }, { label: "slope", value: (math/round (* 1.5 (math/cos (* 0.5 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)))) 1) }, { label: "★", value: @entity.score } ] }
          controls: { type: control-grid, kind: "dpad", directionEvents: { left: "SLOPE_PAD_LEFT", right: "SLOPE_PAD_RIGHT" } }
          overlay: (if (!= @entity.result "none") { type: game-menu, title: @config.clearTitle, subtitle: @config.clearSubtitle, options: [ { id: "next", label: "Next ▶", event: "SLOPE_NEXT", variant: "primary" } ] } null)
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            keyMap: { ArrowLeft: "SLOPE_PUSH_LEFT", KeyA: "SLOPE_PUSH_LEFT", ArrowRight: "SLOPE_PUSH_RIGHT", KeyD: "SLOPE_PUSH_RIGHT" }
            keyUpMap: { ArrowLeft: "SLOPE_PUSH_LEFT_UP", KeyA: "SLOPE_PUSH_LEFT_UP", ArrowRight: "SLOPE_PUSH_RIGHT_UP", KeyD: "SLOPE_PUSH_RIGHT_UP" }
            curves: (array/concat
              [ { label: "f(x) = 3·sin(x/2)", color: "#94a3b8", samples: (array/map (array/range -63 64) (fn i (let ((xx (* @i 0.1))) { x: @xx, y: (* 3 (math/sin (* 0.5 @xx))) }))) } ]
              [ { label: "tangent", color: "#38bdf8", samples: (let ((hx (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) (let ((hy (* 3 (math/sin (* 0.5 @hx))))) (let ((m (* 1.5 (math/cos (* 0.5 @hx))))) [ { x: (- @hx 1.2), y: (- @hy (* @m 1.2)) }, { x: (+ @hx 1.2), y: (+ @hy (* @m 1.2)) } ]))) } ])
            points: (array/concat
              (array/map @entity.features (fn f { x: (object/get @f x), y: (object/get @f y), label: "★", color: @config.starColor, radius: 9 }))
              (array/concat
                [ { x: (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x), y: (* 3 (math/sin (* 0.5 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)))), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/map @entity.fx (fn e { x: (object/get @e x), y: (+ (object/get @e z) 0.6), label: (object/get @e message), color: "#ffe066", radius: 4 }))))
          } ]
        })

      SLOPE_PUSH_LEFT -> idle when (and (== @entity.active true) (and (== @entity.result "none") (!= @entity.holding -1)))
        (set @entity.holding -1)
        (emit SLOPE_THRUST { id: "hero", ax: (- 0 @config.thrust), ay: 0 })

      SLOPE_PUSH_RIGHT -> idle when (and (== @entity.active true) (and (== @entity.result "none") (!= @entity.holding 1)))
        (set @entity.holding 1)
        (emit SLOPE_THRUST { id: "hero", ax: @config.thrust, ay: 0 })

      SLOPE_PUSH_LEFT_UP -> idle when (== @entity.holding -1)
        (set @entity.holding 0)
        (emit SLOPE_THRUST { id: "hero", ax: 0, ay: 0 })

      SLOPE_PUSH_RIGHT_UP -> idle when (== @entity.holding 1)
        (set @entity.holding 0)
        (emit SLOPE_THRUST { id: "hero", ax: 0, ay: 0 })

      SLOPE_PAD_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit SLOPE_IMPULSE { id: "hero", dvx: (- 0 @config.padImpulse), dvy: 0 })

      SLOPE_PAD_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit SLOPE_IMPULSE { id: "hero", dvx: @config.padImpulse, dvy: 0 })

      SLOPE_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "slope" })

      SLOPE_NEXT -> idle
        (navigate @config.nextPath)
    }

    ticks {
      gameTick every 50ms when (and (== @entity.active true) (and (== @entity.result "none") (> (array/len @entity.bodies) 0)))
        (let ((hx (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)))
        (do
          (emit SLOPE_BIAS { biasAx: (- 0 (* @config.hillGravity (* 1.5 (math/cos (* 0.5 @hx))))), biasAy: 0 })
          (let ((matched (array/filter @entity.features (fn f (<= (grid/manhattan-distance { x: (object/get @f x), y: (object/get @f y) } { x: @hx, y: (* 3 (math/sin (* 0.5 @hx))) }) @config.reachRadius)))))
          (if (> (array/len @matched) 0)
            (do
              (set @entity.features (array/filter @entity.features (fn f (> (grid/manhattan-distance { x: (object/get @f x), y: (object/get @f y) } { x: @hx, y: (* 3 (math/sin (* 0.5 @hx))) }) @config.reachRadius))))
              (set @entity.score (+ @entity.score (array/len @matched)))
              (set @entity.objectivesLeft (- @entity.objectivesLeft (array/len @matched)))
              (emit SLOPE_BURST { particles: (array/map @matched (fn f { id: (str/concat "fx-slope-" (object/get @f id)), type: "pickup", x: (object/get @f x), z: (object/get @f y), message: "+1", ttl: 3 })) })
              (emit SLOPE_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 }))
            null))))

      renderTick every 100ms when (and (== @entity.active true) (> (array/len @entity.bodies) 0))
        (render-ui main {
          type: game-shell
          appName: "riya"
          hud: { type: game-hud, stats: [ { label: @config.objectiveText }, { label: "x", value: (math/round (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x) 1) }, { label: "slope", value: (math/round (* 1.5 (math/cos (* 0.5 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)))) 1) }, { label: "★", value: @entity.score } ] }
          controls: { type: control-grid, kind: "dpad", directionEvents: { left: "SLOPE_PAD_LEFT", right: "SLOPE_PAD_RIGHT" } }
          overlay: (if (!= @entity.result "none") { type: game-menu, title: @config.clearTitle, subtitle: @config.clearSubtitle, options: [ { id: "next", label: "Next ▶", event: "SLOPE_NEXT", variant: "primary" } ] } null)
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            keyMap: { ArrowLeft: "SLOPE_PUSH_LEFT", KeyA: "SLOPE_PUSH_LEFT", ArrowRight: "SLOPE_PUSH_RIGHT", KeyD: "SLOPE_PUSH_RIGHT" }
            keyUpMap: { ArrowLeft: "SLOPE_PUSH_LEFT_UP", KeyA: "SLOPE_PUSH_LEFT_UP", ArrowRight: "SLOPE_PUSH_RIGHT_UP", KeyD: "SLOPE_PUSH_RIGHT_UP" }
            curves: (array/concat
              [ { label: "f(x) = 3·sin(x/2)", color: "#94a3b8", samples: (array/map (array/range -63 64) (fn i (let ((xx (* @i 0.1))) { x: @xx, y: (* 3 (math/sin (* 0.5 @xx))) }))) } ]
              [ { label: "tangent", color: "#38bdf8", samples: (let ((hx (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) (let ((hy (* 3 (math/sin (* 0.5 @hx))))) (let ((m (* 1.5 (math/cos (* 0.5 @hx))))) [ { x: (- @hx 1.2), y: (- @hy (* @m 1.2)) }, { x: (+ @hx 1.2), y: (+ @hy (* @m 1.2)) } ]))) } ])
            points: (array/concat
              (array/map @entity.features (fn f { x: (object/get @f x), y: (object/get @f y), label: "★", color: @config.starColor, radius: 9 }))
              (array/concat
                [ { x: (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x), y: (* 3 (math/sin (* 0.5 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)))), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/map @entity.fx (fn e { x: (object/get @e x), y: (+ (object/get @e z) 0.6), label: (object/get @e message), color: "#ffe066", radius: 4 }))))
          } ]
        })
    }


    emits {
      SLOPE_PUSH_LEFT -> external {
        id : string
      }
        @description "Hold-to-push intent from ArrowLeft/KeyA keydown (math-canvas keyMap); guarded on holding-change so OS key-repeat can't re-fire the THRUST emit."
        @tier "domain"
      SLOPE_PUSH_RIGHT -> external {
        id : string
      }
        @description "Hold-to-push intent from ArrowRight/KeyD keydown (math-canvas keyMap); guarded on holding-change so OS key-repeat can't re-fire the THRUST emit."
        @tier "domain"
      SLOPE_PUSH_LEFT_UP -> external {
        id : string
      }
        @description "ArrowLeft/KeyA keyup (math-canvas keyUpMap); releases the player term — only the hill's bias force remains."
        @tier "domain"
      SLOPE_PUSH_RIGHT_UP -> external {
        id : string
      }
        @description "ArrowRight/KeyD keyup (math-canvas keyUpMap); releases the player term — only the hill's bias force remains."
        @tier "domain"
      SLOPE_PAD_LEFT -> external {
        id : string
      }
        @description "D-pad left tap (control-grid directionEvents); applied as an instant velocity kick via SLOPE_IMPULSE."
        @tier "domain"
      SLOPE_PAD_RIGHT -> external {
        id : string
      }
        @description "D-pad right tap (control-grid directionEvents); applied as an instant velocity kick via SLOPE_IMPULSE."
        @tier "domain"
      SLOPE_RESTART -> external {
        id : string
      }
        @description "Reseed broadcast consumed by this world's motion-body/objective-flow authorities (renamed RESTART)."
        @tier "domain"
      SLOPE_THRUST -> external {
        id : string!
        ax : number!
        ay : number!
      }
        @description "Player acceleration term applied by this world's motion-body authority (renamed THRUST); the hill's slope force rides separately on the bias field."
        @tier "domain"
      SLOPE_BIAS -> external {
        biasAx : number!
        biasAy : number!
      }
        @description "Hill-force channel applied by this world's motion-body authority (renamed SET_BIAS); the gameTick re-emits it each tick as -hillGravity · f′(x) so climbing slows riya and descending speeds it."
        @tier "domain"
      SLOPE_IMPULSE -> external {
        id : string!
        dvx : number!
        dvy : number!
      }
        @description "Instant velocity kick applied by this world's motion-body authority (renamed IMPULSE); the d-pad's push."
        @tier "domain"
      SLOPE_BURST -> external {
        particles : [RiyaSlopeFx]
      }
        @description "Pickup particle batch spawned by the gameTick when a star is collected (sparse — only on a catch); fx-particles fades it."
        @tier "domain"
      SLOPE_PROGRESS -> external {
        objectivesLeft : number!
        movesLeft : number!
      }
        @description "Sparse progress signal emitted by the gameTick only when a star is collected; the objective-flow gate resolves won from it."
        @tier "domain"
      SLOPE_GAME_END -> external {
        result : string!
      }
        @description "Win-gate resolution from this world's objective-flow authority (renamed GAME_END); won clears the level."
        @tier "domain"
      RIYA_LEVEL_SOLVED -> external {
        level : string
      }
        @description "Every ★ captured — the win gate resolved won (guarded by celebrated so the gate's repeated GAME_ENDs fire it once)."
        @tier "domain"
      SLOPE_NEXT -> external {
        id : string
      }
        @description "Clear-overlay Next button; navigates to the next world's page."
        @tier "domain"
    }

    config {
      stars : [RiyaSlopeFeature] = [ { id: "s1", x: -3.14, y: -3, type: "star" }, { id: "s2", x: 3.14, y: 3, type: "star" } ]
        @label "Stars"
        @description "Collectible star positions — the valley and the hilltop of 3·sin(x/2), where the slope is exactly 0."
        @tier "domain"
      thrust : number = 12
        @label "Thrust"
        @description "Player acceleration in world units/s² while a direction key is held; always beats the hill's max push (hillGravity · 1.5 = 7.5) so every climb is possible."
        @tier "domain"
      hillGravity : number = 5
        @label "Hill Gravity"
        @description "How hard the slope pushes back: the gameTick writes biasAx = -hillGravity · f′(x); higher makes hills feel steeper."
        @tier "domain"
      padImpulse : number = 2.5
        @label "D-pad Impulse"
        @description "Instant velocity kick in world units/s per d-pad tap."
        @tier "domain"
      reachRadius : number = 0.6
        @label "Reach Radius"
        @description "Manhattan distance at which the gameTick counts a star as collected (measured along the curve)."
        @tier "domain"
      nextPath : string = "/riya-peak"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to."
        @tier "presentation"
      objectiveText : string = "Park riya where the hill is flat — slope 0 ★"
        @label "Objective Text"
        @description "HUD chip telling the player the win condition."
        @tier "presentation"
      clearTitle : string = "Slope clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "You felt the steepness as a push and found where it vanished — that number is the derivative."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
      riyaColor : string = "#dc2626"
        @label "Riya Color"
        @description "Marker color for riya the dot."
        @tier "presentation"
      starColor : string = "#f59e0b"
        @label "Star Color"
        @description "Marker color for uncollected stars."
        @tier "presentation"
      xMin : number = -7
        @label "X Min"
        @description "Left edge of the plotted range in math units."
        @tier "presentation"
      xMax : number = 7
        @label "X Max"
        @description "Right edge of the plotted range in math units."
        @tier "presentation"
      yMin : number = -5
        @label "Y Min"
        @description "Bottom edge of the plotted range."
        @tier "presentation"
      yMax : number = 5
        @label "Y Max"
        @description "Top edge of the plotted range."
        @tier "presentation"
      width : number = 640
        @label "Width"
        @description "Canvas width in pixels."
        @tier "presentation"
      height : number = 360
        @label "Height"
        @description "Canvas height in pixels."
        @tier "presentation"
    }

    listens {
      SlopeGate.SLOPE_GAME_END -> SLOPE_GAME_END
    }
  }

  page "/riya-slope" as RiyaSlopePage -> SlopeMotion, SlopeGate, SlopeFx, RiyaSlopePlay
}


