            keyUpMap: { ArrowLeft: "AREA_PUSH_LEFT_UP", KeyA: "AREA_PUSH_LEFT_UP", ArrowRight: "AREA_PUSH_RIGHT_UP", KeyD: "AREA_PUSH_RIGHT_UP" }
            curves: [ { label: "f(x) = 0.25x + 3", color: "#94a3b8", samples: [ { x: -8, y: 1 }, { x: 8, y: 5 } ] } ]
            bars: (array/map (array/range 0 @entity.painted) (fn i { x: (+ @i -8), width: 1, y0: 0, y1: (+ 3 (* 0.25 (- (+ @i 0.5) 8))), color: "#93c5fd", opacity: 0.6 }))
            points: (array/concat
              (array/map @entity.features (fn f { x: (object/get @f x), y: 0, label: "★", color: (if (and (== @f.id @config.finalStarId) (< @entity.painted 16)) "#64748b" @config.starColor), radius: 9 }))
              (array/concat
                [ { x: (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x), y: 0, label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/map @entity.fx (fn e { x: (object/get @e x), y: 0.6, label: (object/get @e message), color: "#ffe066", radius: 4 }))))
          } ]
        })

      AREA_PUSH_LEFT -> idle when (and (== @entity.active true) (and (== @entity.result "none") (!= @entity.holding -1)))
        (set @entity.holding -1)
        (emit AREA_THRUST { id: "hero", ax: (- 0 @config.thrust), ay: 0 })

      AREA_PUSH_RIGHT -> idle when (and (== @entity.active true) (and (== @entity.result "none") (!= @entity.holding 1)))
        (set @entity.holding 1)
        (emit AREA_THRUST { id: "hero", ax: @config.thrust, ay: 0 })

      AREA_PUSH_LEFT_UP -> idle when (== @entity.holding -1)
        (set @entity.holding 0)
        (emit AREA_THRUST { id: "hero", ax: 0, ay: 0 })

      AREA_PUSH_RIGHT_UP -> idle when (== @entity.holding 1)
        (set @entity.holding 0)
        (emit AREA_THRUST { id: "hero", ax: 0, ay: 0 })

      AREA_PAD_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit AREA_IMPULSE { id: "hero", dvx: (- 0 @config.padImpulse), dvy: 0 })

      AREA_PAD_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit AREA_IMPULSE { id: "hero", dvx: @config.padImpulse, dvy: 0 })

      AREA_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "area" })

      AREA_NEXT -> idle
        (navigate @config.nextPath)
    }

    ticks {
      gameTick every 50ms when (and (== @entity.active true) (and (== @entity.result "none") (> (array/len @entity.bodies) 0)))
        (let ((hx (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)))
        (do
          (if (and (< @entity.painted 16) (> @hx (+ @entity.painted -8)))
            (do
              (set @entity.area (+ @entity.area (+ 3 (* 0.25 (- (+ @entity.painted 0.5) 8)))))
              (set @entity.painted (+ @entity.painted 1)))
            null)
          (let ((matched (array/filter @entity.features (fn f (and (or (>= @entity.painted 16) (!= @f.id @config.finalStarId)) (<= (grid/manhattan-distance { x: (object/get @f x), y: (object/get @f y) } { x: @hx, y: 0 }) @config.reachRadius))))))
          (if (> (array/len @matched) 0)
            (do
              (set @entity.features (array/filter @entity.features (fn f (or (and (< @entity.painted 16) (== @f.id @config.finalStarId)) (> (grid/manhattan-distance { x: (object/get @f x), y: (object/get @f y) } { x: @hx, y: 0 }) @config.reachRadius)))))
              (set @entity.score (+ @entity.score (array/len @matched)))
              (set @entity.objectivesLeft (- @entity.objectivesLeft (array/len @matched)))
              (emit AREA_BURST { particles: (array/map @matched (fn f { id: (str/concat "fx-area-" (object/get @f id)), type: "pickup", x: (object/get @f x), z: (object/get @f y), message: "+1", ttl: 3 })) })
              (emit AREA_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 }))
            null))))

      renderTick every 100ms when (and (== @entity.active true) (> (array/len @entity.bodies) 0))
        (render-ui main {
          type: game-shell
          appName: "riya"
          hud: { type: game-hud, stats: [ { label: @config.objectiveText }, { label: "x", value: (math/round (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x) 1) }, { label: "area", value: (math/round @entity.area 1) }, { label: "strips", value: @entity.painted }, { label: "★", value: @entity.score } ] }
          controls: { type: control-grid, kind: "dpad", directionEvents: { left: "AREA_PAD_LEFT", right: "AREA_PAD_RIGHT" } }
          overlay: (if (!= @entity.result "none") { type: game-menu, title: @config.clearTitle, subtitle: @config.clearSubtitle, options: [ { id: "menu", label: "Menu ★", event: "AREA_NEXT", variant: "primary" } ] } null)
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            keyMap: { ArrowLeft: "AREA_PUSH_LEFT", KeyA: "AREA_PUSH_LEFT", ArrowRight: "AREA_PUSH_RIGHT", KeyD: "AREA_PUSH_RIGHT" }
            keyUpMap: { ArrowLeft: "AREA_PUSH_LEFT_UP", KeyA: "AREA_PUSH_LEFT_UP", ArrowRight: "AREA_PUSH_RIGHT_UP", KeyD: "AREA_PUSH_RIGHT_UP" }
            curves: [ { label: "f(x) = 0.25x + 3", color: "#94a3b8", samples: [ { x: -8, y: 1 }, { x: 8, y: 5 } ] } ]
            bars: (array/map (array/range 0 @entity.painted) (fn i { x: (+ @i -8), width: 1, y0: 0, y1: (+ 3 (* 0.25 (- (+ @i 0.5) 8))), color: "#93c5fd", opacity: 0.6 }))
            points: (array/concat
              (array/map @entity.features (fn f { x: (object/get @f x), y: 0, label: "★", color: (if (and (== @f.id @config.finalStarId) (< @entity.painted 16)) "#64748b" @config.starColor), radius: 9 }))
              (array/concat
                [ { x: (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x), y: 0, label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/map @entity.fx (fn e { x: (object/get @e x), y: 0.6, label: (object/get @e message), color: "#ffe066", radius: 4 }))))
          } ]
        })
    }


    emits {
      AREA_PUSH_LEFT -> external {
        id : string
      }
        @description "Hold-to-push intent from ArrowLeft/KeyA keydown (math-canvas keyMap); guarded on holding-change so OS key-repeat can't re-fire the THRUST emit."
        @tier "domain"
      AREA_PUSH_RIGHT -> external {
        id : string
      }
        @description "Hold-to-push intent from ArrowRight/KeyD keydown (math-canvas keyMap); guarded on holding-change so OS key-repeat can't re-fire the THRUST emit."
        @tier "domain"
      AREA_PUSH_LEFT_UP -> external {
        id : string
      }
        @description "ArrowLeft/KeyA keyup (math-canvas keyUpMap); releases the push so damping coasts riya to a stop."
        @tier "domain"
      AREA_PUSH_RIGHT_UP -> external {
        id : string
      }
        @description "ArrowRight/KeyD keyup (math-canvas keyUpMap); releases the push so damping coasts riya to a stop."
        @tier "domain"
      AREA_PAD_LEFT -> external {
        id : string
      }
        @description "D-pad left tap (control-grid directionEvents); applied as an instant velocity kick via AREA_IMPULSE."
        @tier "domain"
      AREA_PAD_RIGHT -> external {
        id : string
      }
        @description "D-pad right tap (control-grid directionEvents); applied as an instant velocity kick via AREA_IMPULSE."
        @tier "domain"
      AREA_RESTART -> external {
        id : string
      }
        @description "Reseed broadcast consumed by this world's motion-body/objective-flow authorities (renamed RESTART)."
        @tier "domain"
      AREA_THRUST -> external {
        id : string!
        ax : number!
        ay : number!
      }
        @description "Acceleration intent applied by this world's motion-body authority (renamed THRUST); sparse — fired only on keydown/keyup transitions, never per tick."
        @tier "domain"
      AREA_IMPULSE -> external {
        id : string!
        dvx : number!
        dvy : number!
      }
        @description "Instant velocity kick applied by this world's motion-body authority (renamed IMPULSE); the d-pad's push."
        @tier "domain"
      AREA_BURST -> external {
        particles : [RiyaAreaFx]
      }
        @description "Pickup particle batch spawned by the gameTick when a star is collected (sparse — only on a catch); fx-particles fades it."
        @tier "domain"
      AREA_PROGRESS -> external {
        objectivesLeft : number!
        movesLeft : number!
      }
        @description "Sparse progress signal emitted by the gameTick only when a star is collected; the objective-flow gate resolves won from it."
        @tier "domain"
      AREA_GAME_END -> external {
        result : string!
      }
        @description "Win-gate resolution from this world's objective-flow authority (renamed GAME_END); won completes the journey."
        @tier "domain"
      RIYA_LEVEL_SOLVED -> external {
        level : string
      }
        @description "Every ★ captured — the win gate resolved won (guarded by celebrated so the gate's repeated GAME_ENDs fire it once)."
        @tier "domain"
      AREA_NEXT -> external {
        id : string
      }
        @description "Clear-overlay Menu button; navigates back to the menu page."
        @tier "domain"
    }

    config {
      stars : [RiyaAreaFeature] = [ { id: "s1", x: 8, y: 0, type: "star" } ]
        @label "Stars"
        @description "The single end star at the right wall — locked gray until every strip is painted, then it turns gold and collecting it completes the journey."
        @tier "domain"
      finalStarId : string = "s1"
        @label "Final Star Id"
        @description "Id of the concept-gated star: it renders gray and cannot be collected while painted strips < 16 — you cannot finish before the whole sum is laid down."
        @tier "domain"
      thrust : number = 14
        @label "Thrust"
        @description "Acceleration in world units/s² applied while a direction key is held."
        @tier "domain"
      padImpulse : number = 2.5
        @label "D-pad Impulse"
        @description "Instant velocity kick in world units/s per d-pad tap."
        @tier "domain"
      reachRadius : number = 0.6
        @label "Reach Radius"
        @description "Manhattan distance at which the gameTick counts the end star as collected."
        @tier "domain"
      nextPath : string = "/riya"
        @label "Next Path"
        @description "Page the clear overlay's Menu button navigates to (the menu — this is the final world)."
        @tier "presentation"
      objectiveText : string = "Paint 16 strips to turn the gray ★ gold"
        @label "Objective Text"
        @description "HUD chip telling the player the win condition."
        @tier "presentation"
      clearTitle : string = "RIYA COMPLETE ★"
        @label "Clear Title"
        @description "Overlay title once the final star is collected — the whole journey is done."
        @tier "presentation"
      clearSubtitle : string = "You carried riya from a number on a line all the way to the area under a curve — 48 square units, one strip at a time."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
      riyaColor : string = "#dc2626"
        @label "Riya Color"
        @description "Marker color for riya the dot."
        @tier "presentation"
      starColor : string = "#f59e0b"
        @label "Star Color"
        @description "Marker color for the uncollected end star."
        @tier "presentation"
      xMin : number = -9
        @label "X Min"
        @description "Left edge of the plotted range in math units."
        @tier "presentation"
      xMax : number = 9
        @label "X Max"
        @description "Right edge of the plotted range in math units."
        @tier "presentation"
      yMin : number = -1
        @label "Y Min"
        @description "Bottom edge of the plotted range."
        @tier "presentation"
      yMax : number = 6
        @label "Y Max"
        @description "Top edge of the plotted range."
        @tier "presentation"
      width : number = 640
        @label "Width"
        @description "Canvas width in pixels."
        @tier "presentation"
      height : number = 360
        @label "Height"
        @description "Canvas height in pixels."
        @tier "presentation"
    }

    listens {
      AreaGate.AREA_GAME_END -> AREA_GAME_END
    }
  }

  page "/riya-area" as RiyaAreaPage -> AreaMotion, AreaGate, AreaFx, RiyaAreaPlay
}


orbital RiyaPeakOrbital {
  uses Motion from "std/behaviors/std-motion-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"

  type RiyaPeakBody = {
    id : string!
    x : number!
    y : number!
    vx : number
    vy : number
    ax : number
    ay : number
  }
  type RiyaPeakFeature = {
    id : string
    x : number!
    y : number!
    z : number
    type : string!
    color : string
    elevation : number
    done : boolean
  }
  type RiyaPeakFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
  }

  entity RiyaPeakState [runtime, shared] {
    id : string!
    active : boolean = false
    bodies : [RiyaPeakBody] = []
    gravity : number = 0
    biasAx : number = 0
    biasAy : number = 0
    features : [RiyaPeakFeature] = []
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaPeakFx] = []
    holding : number = 0
    celebrated : boolean = false
  }

  trait PeakMotion = Motion.traits.MotionBody -> RiyaPeakState {
    events {
      THRUST: PEAK_THRUST
      IMPULSE: PEAK_IMPULSE
      PLACE: PEAK_PLACE
      SET_GRAVITY: PEAK_SET_GRAVITY
      SET_BIAS: PEAK_BIAS
      RESTART: PEAK_RESTART
      BODY_MOVED: PEAK_MOVED
    }
    config {
      running: true
      gravity: 0
      damping: 0.97
      maxSpeed: 7
      xMin: -2.2
      xMax: 2.2
      yMin: -3
      yMax: 3
      bodies: [ { id: "hero", x: -2, y: 0, vx: 0, vy: 0, ax: 0, ay: 0 } ]
    }

    listens {
      THRUST { id : string!, ax : number!, ay : number! }
      IMPULSE { id : string!, dvx : number!, dvy : number! }
      PLACE { id : string!, x : number!, y : number! }
      SET_GRAVITY { gravity : number! }
      SET_BIAS { biasAx : number!, biasAy : number! }
      RESTART { id : string }
      RiyaPeakPlay.PEAK_BIAS -> PEAK_BIAS
      RiyaPeakPlay.PEAK_IMPULSE -> PEAK_IMPULSE
      RiyaPeakPlay.PEAK_RESTART -> PEAK_RESTART
      RiyaPeakPlay.PEAK_THRUST -> PEAK_THRUST
    }
  }

  trait PeakGate = Gate.traits.ObjectiveFlow -> RiyaPeakState {
    events {
      PROGRESS: PEAK_PROGRESS
      GAME_END: PEAK_GAME_END
      RESTART: PEAK_RESTART
    }
    config { running: true }

    listens {
      PROGRESS { objectivesLeft : number, movesLeft : number }
      RESTART { id : string }
      RiyaPeakPlay.PEAK_PROGRESS -> PEAK_PROGRESS
      RiyaPeakPlay.PEAK_RESTART -> PEAK_RESTART
    }
  }

  trait PeakFx = Particles.traits.FxParticles -> RiyaPeakState {
    events {
      BURST: PEAK_BURST
    }
    config { running: true }

    listens {
      BURST { particles : [Fx] }
      RESTART { }
      RiyaPeakPlay.PEAK_BURST -> PEAK_BURST
    }
  }

  trait RiyaPeakPlay -> @rebindable RiyaPeakState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.holding 0)
        (set @entity.celebrated false)
        (set @entity.features @config.stars)
        (set @entity.score 0)
        (set @entity.objectivesLeft (array/len @config.stars))
        (emit PEAK_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: "riya"
          hud: { type: game-hud, stats: [ { label: @config.objectiveText }, { label: "x", value: (math/round (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x) 1) }, { label: "f(x)", value: (math/round (- (* 0.5 (* (* (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x) (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)) (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) (* 1.5 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) 1) }, { label: "slope", value: (math/round (- (* 1.5 (* (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x) (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) 1.5) 1) }, { label: "★", value: @entity.score } ] }
          controls: { type: control-grid, kind: "dpad", directionEvents: { left: "PEAK_PAD_LEFT", right: "PEAK_PAD_RIGHT" } }
          overlay: (if (!= @entity.result "none") { type: game-menu, title: @config.clearTitle, subtitle: @config.clearSubtitle, options: [ { id: "next", label: "Next ▶", event: "PEAK_NEXT", variant: "primary" } ] } null)
          children: [ {
