            curves: (array/concat
              [ { label: "f(x) = 0.5x³ − 1.5x", color: "#94a3b8", samples: (array/map (array/range -22 23) (fn i (let ((xx (* @i 0.1))) { x: @xx, y: (- (* 0.5 (* (* @xx @xx) @xx)) (* 1.5 @xx)) }))) } ]
              [ { label: "tangent", color: "#38bdf8", samples: (let ((hx (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) (let ((hy (- (* 0.5 (* (* @hx @hx) @hx)) (* 1.5 @hx)))) (let ((m (- (* 1.5 (* @hx @hx)) 1.5))) [ { x: (- @hx 0.8), y: (- @hy (* @m 0.8)) }, { x: (+ @hx 0.8), y: (+ @hy (* @m 0.8)) } ]))) } ])
            points: (array/concat
              (array/map @entity.features (fn f { x: (object/get @f x), y: (object/get @f y), label: "★", color: @config.starColor, radius: 9 }))
              (array/concat
                [ { x: (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x), y: (- (* 0.5 (* (* (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x) (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)) (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) (* 1.5 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/map @entity.fx (fn e { x: (object/get @e x), y: (+ (object/get @e z) 0.6), label: (object/get @e message), color: "#ffe066", radius: 4 }))))
          } ]
        })

      PEAK_PUSH_LEFT -> idle when (and (== @entity.active true) (and (== @entity.result "none") (!= @entity.holding -1)))
        (set @entity.holding -1)
        (emit PEAK_THRUST { id: "hero", ax: (- 0 @config.thrust), ay: 0 })

      PEAK_PUSH_RIGHT -> idle when (and (== @entity.active true) (and (== @entity.result "none") (!= @entity.holding 1)))
        (set @entity.holding 1)
        (emit PEAK_THRUST { id: "hero", ax: @config.thrust, ay: 0 })

      PEAK_PUSH_LEFT_UP -> idle when (== @entity.holding -1)
        (set @entity.holding 0)
        (emit PEAK_THRUST { id: "hero", ax: 0, ay: 0 })

      PEAK_PUSH_RIGHT_UP -> idle when (== @entity.holding 1)
        (set @entity.holding 0)
        (emit PEAK_THRUST { id: "hero", ax: 0, ay: 0 })

      PEAK_PAD_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit PEAK_IMPULSE { id: "hero", dvx: (- 0 @config.padImpulse), dvy: 0 })

      PEAK_PAD_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit PEAK_IMPULSE { id: "hero", dvx: @config.padImpulse, dvy: 0 })

      PEAK_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "peak" })

      PEAK_NEXT -> idle
        (navigate @config.nextPath)
    }

    ticks {
      gameTick every 50ms when (and (== @entity.active true) (and (== @entity.result "none") (> (array/len @entity.bodies) 0)))
        (let ((hx (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)))
        (do
          (emit PEAK_BIAS { biasAx: (- 0 (* @config.hillGravity (- (* 1.5 (* @hx @hx)) 1.5))), biasAy: 0 })
          (let ((matched (array/filter @entity.features (fn f (<= (grid/manhattan-distance { x: (object/get @f x), y: (object/get @f y) } { x: @hx, y: (- (* 0.5 (* (* @hx @hx) @hx)) (* 1.5 @hx)) }) @config.reachRadius)))))
          (if (> (array/len @matched) 0)
            (do
              (set @entity.features (array/filter @entity.features (fn f (> (grid/manhattan-distance { x: (object/get @f x), y: (object/get @f y) } { x: @hx, y: (- (* 0.5 (* (* @hx @hx) @hx)) (* 1.5 @hx)) }) @config.reachRadius))))
              (set @entity.score (+ @entity.score (array/len @matched)))
              (set @entity.objectivesLeft (- @entity.objectivesLeft (array/len @matched)))
              (emit PEAK_BURST { particles: (array/map @matched (fn f { id: (str/concat "fx-peak-" (object/get @f id)), type: "pickup", x: (object/get @f x), z: (object/get @f y), message: "+1", ttl: 3 })) })
              (emit PEAK_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 }))
            null))))

      renderTick every 100ms when (and (== @entity.active true) (> (array/len @entity.bodies) 0))
        (render-ui main {
