          appName: "riya"
          hud: { type: game-hud, stats: [ { label: @config.objectiveText }, { label: "x", value: (math/round (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x) 1) }, { label: "f(x)", value: (math/round (- (* 0.5 (* (* (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x) (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)) (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) (* 1.5 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) 1) }, { label: "slope", value: (math/round (- (* 1.5 (* (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x) (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) 1.5) 1) }, { label: "★", value: @entity.score } ] }
          controls: { type: control-grid, kind: "dpad", directionEvents: { left: "PEAK_PAD_LEFT", right: "PEAK_PAD_RIGHT" } }
          overlay: (if (!= @entity.result "none") { type: game-menu, title: @config.clearTitle, subtitle: @config.clearSubtitle, options: [ { id: "next", label: "Next ▶", event: "PEAK_NEXT", variant: "primary" } ] } null)
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            keyMap: { ArrowLeft: "PEAK_PUSH_LEFT", KeyA: "PEAK_PUSH_LEFT", ArrowRight: "PEAK_PUSH_RIGHT", KeyD: "PEAK_PUSH_RIGHT" }
            keyUpMap: { ArrowLeft: "PEAK_PUSH_LEFT_UP", KeyA: "PEAK_PUSH_LEFT_UP", ArrowRight: "PEAK_PUSH_RIGHT_UP", KeyD: "PEAK_PUSH_RIGHT_UP" }
            curves: (array/concat
              [ { label: "f(x) = 0.5x³ − 1.5x", color: "#94a3b8", samples: (array/map (array/range -22 23) (fn i (let ((xx (* @i 0.1))) { x: @xx, y: (- (* 0.5 (* (* @xx @xx) @xx)) (* 1.5 @xx)) }))) } ]
              [ { label: "tangent", color: "#38bdf8", samples: (let ((hx (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) (let ((hy (- (* 0.5 (* (* @hx @hx) @hx)) (* 1.5 @hx)))) (let ((m (- (* 1.5 (* @hx @hx)) 1.5))) [ { x: (- @hx 0.8), y: (- @hy (* @m 0.8)) }, { x: (+ @hx 0.8), y: (+ @hy (* @m 0.8)) } ]))) } ])
            points: (array/concat
              (array/map @entity.features (fn f { x: (object/get @f x), y: (object/get @f y), label: "★", color: @config.starColor, radius: 9 }))
              (array/concat
                [ { x: (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x), y: (- (* 0.5 (* (* (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x) (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)) (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) (* 1.5 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/map @entity.fx (fn e { x: (object/get @e x), y: (+ (object/get @e z) 0.6), label: (object/get @e message), color: "#ffe066", radius: 4 }))))
          } ]
        })
    }


    emits {
      PEAK_PUSH_LEFT -> external {
        id : string
      }
        @description "Hold-to-push intent from ArrowLeft/KeyA keydown (math-canvas keyMap); guarded on holding-change so OS key-repeat can't re-fire the THRUST emit."
        @tier "domain"
      PEAK_PUSH_RIGHT -> external {
        id : string
      }
        @description "Hold-to-push intent from ArrowRight/KeyD keydown (math-canvas keyMap); guarded on holding-change so OS key-repeat can't re-fire the THRUST emit."
        @tier "domain"
      PEAK_PUSH_LEFT_UP -> external {
        id : string
      }
        @description "ArrowLeft/KeyA keyup (math-canvas keyUpMap); releases the player term — only the hill's bias force remains."
        @tier "domain"
      PEAK_PUSH_RIGHT_UP -> external {
        id : string
      }
        @description "ArrowRight/KeyD keyup (math-canvas keyUpMap); releases the player term — only the hill's bias force remains."
        @tier "domain"
      PEAK_PAD_LEFT -> external {
        id : string
      }
        @description "D-pad left tap (control-grid directionEvents); applied as an instant velocity kick via PEAK_IMPULSE."
        @tier "domain"
      PEAK_PAD_RIGHT -> external {
        id : string
      }
        @description "D-pad right tap (control-grid directionEvents); applied as an instant velocity kick via PEAK_IMPULSE."
        @tier "domain"
      PEAK_RESTART -> external {
        id : string
      }
        @description "Reseed broadcast consumed by this world's motion-body/objective-flow authorities (renamed RESTART)."
        @tier "domain"
      PEAK_THRUST -> external {
        id : string!
        ax : number!
        ay : number!
      }
        @description "Player acceleration term applied by this world's motion-body authority (renamed THRUST); the hill's slope force rides separately on the bias field."
        @tier "domain"
      PEAK_BIAS -> external {
        biasAx : number!
        biasAy : number!
      }
        @description "Hill-force channel applied by this world's motion-body authority (renamed SET_BIAS); the gameTick re-emits it each tick as -hillGravity · f′(x) for the cubic, so riya slows on climbs and speeds on descents."
        @tier "domain"
      PEAK_IMPULSE -> external {
        id : string!
        dvx : number!
        dvy : number!
      }
        @description "Instant velocity kick applied by this world's motion-body authority (renamed IMPULSE); the d-pad's push."
        @tier "domain"
      PEAK_BURST -> external {
        particles : [RiyaPeakFx]
      }
        @description "Pickup particle batch spawned by the gameTick when a star is collected (sparse — only on a catch); fx-particles fades it."
        @tier "domain"
      PEAK_PROGRESS -> external {
        objectivesLeft : number!
        movesLeft : number!
      }
        @description "Sparse progress signal emitted by the gameTick only when a star is collected; the objective-flow gate resolves won from it."
        @tier "domain"
      PEAK_GAME_END -> external {
        result : string!
      }
        @description "Win-gate resolution from this world's objective-flow authority (renamed GAME_END); won clears the level."
        @tier "domain"
      RIYA_LEVEL_SOLVED -> external {
        level : string
      }
        @description "Every ★ captured — the win gate resolved won (guarded by celebrated so the gate's repeated GAME_ENDs fire it once)."
        @tier "domain"
      PEAK_NEXT -> external {
        id : string
      }
        @description "Clear-overlay Next button; navigates to the next world's page."
        @tier "domain"
    }

    config {
      stars : [RiyaPeakFeature] = [ { id: "s1", x: -1, y: 1, type: "star" }, { id: "s2", x: 1, y: -1, type: "star" } ]
        @label "Stars"
        @description "Collectible star positions — the hilltop (-1, 1) and the valley (1, -1) of 0.5x³ − 1.5x, where the slope is exactly 0."
        @tier "domain"
      thrust : number = 14
        @label "Thrust"
        @description "Player acceleration in world units/s² while a direction key is held; always beats the hill's max push (hillGravity · 5.76 = 11.5) so every climb is possible."
        @tier "domain"
      hillGravity : number = 2
        @label "Hill Gravity"
        @description "How hard the slope pushes back: the gameTick writes biasAx = -hillGravity · f′(x); higher makes hills feel steeper."
        @tier "domain"
      padImpulse : number = 2.5
        @label "D-pad Impulse"
        @description "Instant velocity kick in world units/s per d-pad tap."
        @tier "domain"
      reachRadius : number = 0.6
        @label "Reach Radius"
        @description "Manhattan distance at which the gameTick counts a star as collected (measured along the curve)."
        @tier "domain"
      nextPath : string = "/riya-limit"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to."
        @tier "presentation"
      objectiveText : string = "Ride over the hilltop and the valley — slope 0 at both ★"
        @label "Objective Text"
        @description "HUD chip telling the player the win condition."
        @tier "presentation"
      clearTitle : string = "Peak clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "A curvy rule has flat spots at its very top and bottom — the turning points, where the slope passes through 0."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
      riyaColor : string = "#dc2626"
        @label "Riya Color"
        @description "Marker color for riya the dot."
        @tier "presentation"
      starColor : string = "#f59e0b"
        @label "Star Color"
        @description "Marker color for uncollected stars."
        @tier "presentation"
      xMin : number = -2.6
        @label "X Min"
        @description "Left edge of the plotted range in math units."
        @tier "presentation"
      xMax : number = 2.6
        @label "X Max"
        @description "Right edge of the plotted range in math units."
        @tier "presentation"
      yMin : number = -3
        @label "Y Min"
        @description "Bottom edge of the plotted range."
        @tier "presentation"
      yMax : number = 3
        @label "Y Max"
        @description "Top edge of the plotted range."
        @tier "presentation"
      width : number = 640
        @label "Width"
        @description "Canvas width in pixels."
        @tier "presentation"
      height : number = 360
        @label "Height"
        @description "Canvas height in pixels."
        @tier "presentation"
    }

    listens {
      PeakGate.PEAK_GAME_END -> PEAK_GAME_END
    }
  }

  page "/riya-peak" as RiyaPeakPage -> PeakMotion, PeakGate, PeakFx, RiyaPeakPlay
}


orbital RiyaLimitOrbital {
  uses Motion from "std/behaviors/std-motion-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"

  type RiyaLimitBody = {
    id : string!
    x : number!
    y : number!
    vx : number
    vy : number
    ax : number
    ay : number
  }
  type RiyaLimitFeature = {
    id : string
    x : number!
    y : number!
    z : number
    type : string!
    color : string
    elevation : number
    done : boolean
  }
  type RiyaLimitFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
  }

  entity RiyaLimitState [runtime, shared] {
    id : string!
    active : boolean = false
    bodies : [RiyaLimitBody] = []
    gravity : number = 0
    biasAx : number = 0
    biasAy : number = 0
    features : [RiyaLimitFeature] = []
    collected : [RiyaLimitFeature] = []
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaLimitFx] = []
    holding : number = 0
    celebrated : boolean = false
    inDanger : boolean = false
  }

  trait LimitMotion = Motion.traits.MotionBody -> RiyaLimitState {
    events {
      THRUST: LIMIT_THRUST
      IMPULSE: LIMIT_IMPULSE
      PLACE: LIMIT_PLACE
      SET_GRAVITY: LIMIT_SET_GRAVITY
      RESTART: LIMIT_RESTART
      BODY_MOVED: LIMIT_MOVED
    }
    config {
      running: true
      gravity: 0
      damping: 0.94
      maxSpeed: 7
      xMin: 0.6
      xMax: 8.6
      yMin: -1
      yMax: 10
      bodies: [ { id: "hero", x: 8, y: 0, vx: 0, vy: 0, ax: 0, ay: 0 } ]
    }

    listens {
      THRUST { id : string!, ax : number!, ay : number! }
      IMPULSE { id : string!, dvx : number!, dvy : number! }
      PLACE { id : string!, x : number!, y : number! }
      SET_GRAVITY { gravity : number! }
      SET_BIAS { biasAx : number!, biasAy : number! }
      RESTART { id : string }
      RiyaLimitPlay.LIMIT_IMPULSE -> LIMIT_IMPULSE
      RiyaLimitPlay.LIMIT_RESTART -> LIMIT_RESTART
      RiyaLimitPlay.LIMIT_THRUST -> LIMIT_THRUST
    }
  }

  trait LimitGate = Gate.traits.ObjectiveFlow -> RiyaLimitState {
    events {
      PROGRESS: LIMIT_PROGRESS
      GAME_END: LIMIT_GAME_END
      RESTART: LIMIT_RESTART
    }
    config { running: true }

    listens {
      PROGRESS { objectivesLeft : number, movesLeft : number }
      RESTART { id : string }
      RiyaLimitPlay.LIMIT_PROGRESS -> LIMIT_PROGRESS
      RiyaLimitPlay.LIMIT_RESTART -> LIMIT_RESTART
    }
  }

  trait LimitFx = Particles.traits.FxParticles -> RiyaLimitState {
    events {
      BURST: LIMIT_BURST
    }
    config { running: true }

    listens {
      BURST { particles : [Fx] }
      RESTART { }
      RiyaLimitPlay.LIMIT_BURST -> LIMIT_BURST
    }
  }

  trait RiyaLimitPlay -> @rebindable RiyaLimitState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.holding 0)
        (set @entity.celebrated false)
        (set @entity.inDanger false)
        (set @entity.features @config.stars)
        (set @entity.collected [])
        (set @entity.score 0)
        (set @entity.objectivesLeft (array/len @config.stars))
        (emit LIMIT_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: "riya"
          hud: { type: game-hud, stats: [ { label: @config.objectiveText }, { label: "x", value: (math/round (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x) 1) }, { label: "f(x)", value: (math/round (/ 8 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)) 1) }, { label: "★", value: @entity.score } ] }
          controls: { type: control-grid, kind: "dpad", directionEvents: { left: "LIMIT_PAD_LEFT", right: "LIMIT_PAD_RIGHT" } }
          overlay: (if (!= @entity.result "none") { type: game-menu, title: @config.clearTitle, subtitle: @config.clearSubtitle, options: [ { id: "next", label: "Next ▶", event: "LIMIT_NEXT", variant: "primary" } ] } null)
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            keyMap: { ArrowLeft: "LIMIT_PUSH_LEFT", KeyA: "LIMIT_PUSH_LEFT", ArrowRight: "LIMIT_PUSH_RIGHT", KeyD: "LIMIT_PUSH_RIGHT" }
            keyUpMap: { ArrowLeft: "LIMIT_PUSH_LEFT_UP", KeyA: "LIMIT_PUSH_LEFT_UP", ArrowRight: "LIMIT_PUSH_RIGHT_UP", KeyD: "LIMIT_PUSH_RIGHT_UP" }
            curves: (array/concat
              [ { label: "f(x) = 8/x", color: "#94a3b8", samples: (array/map (array/range 6 90) (fn i (let ((xx (* @i 0.1))) { x: @xx, y: (/ 8 @xx) }))) } ]
              (array/concat
                [ { label: "x = 0", color: "#f87171", samples: [ { x: 0, y: -1 }, { x: 0, y: 10 } ] } ]
                [ { label: "danger", color: "#fb923c", samples: [ { x: @config.dangerX, y: -1 }, { x: @config.dangerX, y: 10 } ] } ]))
            points: (array/concat
              (array/map @entity.features (fn f { x: (object/get @f x), y: (object/get @f y), label: "★", color: @config.starColor, radius: 9 }))
              (array/concat
                [ { x: (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x), y: (/ 8 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/map @entity.fx (fn e { x: (object/get @e x), y: (+ (object/get @e z) 0.6), label: (object/get @e message), color: "#ffe066", radius: 4 }))))
            vectors: [ { x: (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x), y: (/ 8 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)), vx: (* (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) vx) 0.3), vy: 0, color: @config.riyaColor, label: "v" } ]
          } ]
        })

      LIMIT_PUSH_LEFT -> idle when (and (== @entity.active true) (and (== @entity.result "none") (!= @entity.holding -1)))
        (set @entity.holding -1)
        (emit LIMIT_THRUST { id: "hero", ax: (- 0 @config.thrust), ay: 0 })

      LIMIT_PUSH_RIGHT -> idle when (and (== @entity.active true) (and (== @entity.result "none") (!= @entity.holding 1)))
        (set @entity.holding 1)
        (emit LIMIT_THRUST { id: "hero", ax: @config.thrust, ay: 0 })

      LIMIT_PUSH_LEFT_UP -> idle when (== @entity.holding -1)
        (set @entity.holding 0)
        (emit LIMIT_THRUST { id: "hero", ax: 0, ay: 0 })

      LIMIT_PUSH_RIGHT_UP -> idle when (== @entity.holding 1)
        (set @entity.holding 0)
        (emit LIMIT_THRUST { id: "hero", ax: 0, ay: 0 })

      LIMIT_PAD_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit LIMIT_IMPULSE { id: "hero", dvx: (- 0 @config.padImpulse), dvy: 0 })

      LIMIT_PAD_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit LIMIT_IMPULSE { id: "hero", dvx: @config.padImpulse, dvy: 0 })

      LIMIT_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "limit" })

      LIMIT_NEXT -> idle
        (navigate @config.nextPath)
    }

    ticks {
      gameTick every 50ms when (and (== @entity.active true) (and (== @entity.result "none") (> (array/len @entity.bodies) 0)))
        (let ((hx (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)))
        (do
          (let ((matched (array/filter @entity.features (fn f (<= (grid/manhattan-distance { x: (object/get @f x), y: (object/get @f y) } { x: @hx, y: (/ 8 @hx) }) @config.reachRadius)))))
          (if (> (array/len @matched) 0)
            (do
              (set @entity.features (array/filter @entity.features (fn f (> (grid/manhattan-distance { x: (object/get @f x), y: (object/get @f y) } { x: @hx, y: (/ 8 @hx) }) @config.reachRadius))))
              (set @entity.collected (array/concat @entity.collected @matched))
              (set @entity.score (+ @entity.score (array/len @matched)))
              (set @entity.objectivesLeft (- @entity.objectivesLeft (array/len @matched)))
              (emit LIMIT_BURST { particles: (array/map @matched (fn f { id: (str/concat "fx-limit-" (object/get @f id)), type: "pickup", x: (object/get @f x), z: (object/get @f y), message: "+1", ttl: 3 })) })
              (emit LIMIT_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 }))
            null))
          (if (>= @hx @config.dangerX)
            (set @entity.inDanger false)
            null)
          (if (< @hx @config.dangerX)
            (do
              (emit LIMIT_IMPULSE { id: "hero", dvx: @config.flingImpulse, dvy: 0 })
              (if (and (== @entity.inDanger false) (> (array/len @entity.collected) 0))
                (do
                  (set @entity.inDanger true)
                  (set @entity.features (array/concat @entity.features [ (array/last @entity.collected) ]))
                  (set @entity.collected (array/filter @entity.collected (fn f (!= @f.id (object/get (array/last @entity.collected) id)))))
                  (set @entity.score (- @entity.score 1))
                  (set @entity.objectivesLeft (+ @entity.objectivesLeft 1))
                  (emit LIMIT_BURST { particles: [ { id: "fx-limit-danger", type: "hit", x: @hx, z: (/ 8 @hx), message: "-1 ★", ttl: 3 } ] }))
                null))
            null)))

      renderTick every 100ms when (and (== @entity.active true) (> (array/len @entity.bodies) 0))
        (render-ui main {
          type: game-shell
          appName: "riya"
          hud: { type: game-hud, stats: [ { label: @config.objectiveText }, { label: "x", value: (math/round (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x) 1) }, { label: "f(x)", value: (math/round (/ 8 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)) 1) }, { label: "★", value: @entity.score } ] }
          controls: { type: control-grid, kind: "dpad", directionEvents: { left: "LIMIT_PAD_LEFT", right: "LIMIT_PAD_RIGHT" } }
          overlay: (if (!= @entity.result "none") { type: game-menu, title: @config.clearTitle, subtitle: @config.clearSubtitle, options: [ { id: "next", label: "Next ▶", event: "LIMIT_NEXT", variant: "primary" } ] } null)
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            keyMap: { ArrowLeft: "LIMIT_PUSH_LEFT", KeyA: "LIMIT_PUSH_LEFT", ArrowRight: "LIMIT_PUSH_RIGHT", KeyD: "LIMIT_PUSH_RIGHT" }
            keyUpMap: { ArrowLeft: "LIMIT_PUSH_LEFT_UP", KeyA: "LIMIT_PUSH_LEFT_UP", ArrowRight: "LIMIT_PUSH_RIGHT_UP", KeyD: "LIMIT_PUSH_RIGHT_UP" }
            curves: (array/concat
              [ { label: "f(x) = 8/x", color: "#94a3b8", samples: (array/map (array/range 6 90) (fn i (let ((xx (* @i 0.1))) { x: @xx, y: (/ 8 @xx) }))) } ]
              (array/concat
                [ { label: "x = 0", color: "#f87171", samples: [ { x: 0, y: -1 }, { x: 0, y: 10 } ] } ]
                [ { label: "danger", color: "#fb923c", samples: [ { x: @config.dangerX, y: -1 }, { x: @config.dangerX, y: 10 } ] } ]))
            points: (array/concat
              (array/map @entity.features (fn f { x: (object/get @f x), y: (object/get @f y), label: "★", color: @config.starColor, radius: 9 }))
              (array/concat
                [ { x: (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x), y: (/ 8 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/map @entity.fx (fn e { x: (object/get @e x), y: (+ (object/get @e z) 0.6), label: (object/get @e message), color: "#ffe066", radius: 4 }))))
            vectors: [ { x: (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x), y: (/ 8 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)), vx: (* (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) vx) 0.3), vy: 0, color: @config.riyaColor, label: "v" } ]
          } ]
        })
    }


    emits {
      LIMIT_PUSH_LEFT -> external {
        id : string
      }
        @description "Hold-to-push intent from ArrowLeft/KeyA keydown (math-canvas keyMap); guarded on holding-change so OS key-repeat can't re-fire the THRUST emit."
        @tier "domain"
      LIMIT_PUSH_RIGHT -> external {
        id : string
      }
        @description "Hold-to-push intent from ArrowRight/KeyD keydown (math-canvas keyMap); guarded on holding-change so OS key-repeat can't re-fire the THRUST emit."
        @tier "domain"
      LIMIT_PUSH_LEFT_UP -> external {
        id : string
      }
        @description "ArrowLeft/KeyA keyup (math-canvas keyUpMap); releases the push so damping coasts riya to a stop."
        @tier "domain"
      LIMIT_PUSH_RIGHT_UP -> external {
        id : string
      }
        @description "ArrowRight/KeyD keyup (math-canvas keyUpMap); releases the push so damping coasts riya to a stop."
        @tier "domain"
      LIMIT_PAD_LEFT -> external {
        id : string
      }
        @description "D-pad left tap (control-grid directionEvents); applied as an instant velocity kick via LIMIT_IMPULSE."
        @tier "domain"
      LIMIT_PAD_RIGHT -> external {
        id : string
      }
        @description "D-pad right tap (control-grid directionEvents); applied as an instant velocity kick via LIMIT_IMPULSE."
        @tier "domain"
      LIMIT_RESTART -> external {
        id : string
      }
        @description "Reseed broadcast consumed by this world's motion-body/objective-flow authorities (renamed RESTART)."
        @tier "domain"
      LIMIT_THRUST -> external {
        id : string!
        ax : number!
        ay : number!
      }
        @description "Acceleration intent applied by this world's motion-body authority (renamed THRUST); sparse — fired only on keydown/keyup transitions, never per tick."
        @tier "domain"
      LIMIT_IMPULSE -> external {
        id : string!
        dvx : number!
        dvy : number!
      }
        @description "Instant velocity kick applied by this world's motion-body authority (renamed IMPULSE); the d-pad's push."
        @tier "domain"
      LIMIT_BURST -> external {
        particles : [RiyaLimitFx]
      }
        @description "Pickup particle batch spawned by the gameTick when a star is collected (sparse — only on a catch); fx-particles fades it."
        @tier "domain"
      LIMIT_PROGRESS -> external {
        objectivesLeft : number!
        movesLeft : number!
      }
        @description "Sparse progress signal emitted by the gameTick only when a star is collected; the objective-flow gate resolves won from it."
        @tier "domain"
      LIMIT_GAME_END -> external {
        result : string!
      }
        @description "Win-gate resolution from this world's objective-flow authority (renamed GAME_END); won clears the level."
        @tier "domain"
      RIYA_LEVEL_SOLVED -> external {
        level : string
      }
        @description "Every ★ captured — the win gate resolved won (guarded by celebrated so the gate's repeated GAME_ENDs fire it once)."
        @tier "domain"
      LIMIT_NEXT -> external {
        id : string
      }
        @description "Clear-overlay Next button; navigates to the next world's page."
        @tier "domain"
    }

    config {
      stars : [RiyaLimitFeature] = [ { id: "s1", x: 1, y: 8, type: "star" }, { id: "s2", x: 2, y: 4, type: "star" }, { id: "s3", x: 4, y: 2, type: "star" }, { id: "s4", x: 8, y: 1, type: "star" } ]
        @label "Stars"
        @description "Collectible star positions — exact points of f(x) = 8/x; the highest one guards the approach to the asymptote."
        @tier "domain"
      thrust : number = 14
        @label "Thrust"
        @description "Acceleration in world units/s² applied while a direction key is held."
        @tier "domain"
      padImpulse : number = 2.5
        @label "D-pad Impulse"
        @description "Instant velocity kick in world units/s per d-pad tap."
        @tier "domain"
      reachRadius : number = 0.6
        @label "Reach Radius"
        @description "Manhattan distance at which the gameTick counts a star as collected (measured along the curve)."
        @tier "domain"
      dangerX : number = 0.85
        @label "Danger Line"
        @description "Crossing this x toward the pole flings riya back and costs the last collected ★ — sits safely below the top star's collection window (~0.93) so grabbing it never triggers the hazard; the asymptote is not a place you can stand."
        @tier "domain"
      flingImpulse : number = 6
        @label "Fling Impulse"
        @description "Velocity kick in world units/s applied every tick while riya is past the danger line — the pole physically repels."
        @tier "domain"
      nextPath : string = "/riya-expo"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to."
        @tier "presentation"
      objectiveText : string = "Catch all 4 ★ on f(x) = 8/x — but the pole flings you back and takes a ★"
        @label "Objective Text"
        @description "HUD chip telling the player the win condition."
        @tier "presentation"
      clearTitle : string = "Limit clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "Closer and closer to x = 0 the number grew and grew — nearer forever, never arriving. That feeling is a limit."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
      riyaColor : string = "#dc2626"
        @label "Riya Color"
        @description "Marker color for riya the dot."
        @tier "presentation"
      starColor : string = "#f59e0b"
        @label "Star Color"
        @description "Marker color for uncollected stars."
        @tier "presentation"
      xMin : number = 0
        @label "X Min"
        @description "Left edge of the plotted range in math units."
        @tier "presentation"
      xMax : number = 9
        @label "X Max"
        @description "Right edge of the plotted range in math units."
        @tier "presentation"
      yMin : number = -1
        @label "Y Min"
        @description "Bottom edge of the plotted range."
        @tier "presentation"
      yMax : number = 10
        @label "Y Max"
        @description "Top edge of the plotted range."
        @tier "presentation"
      width : number = 640
        @label "Width"
        @description "Canvas width in pixels."
        @tier "presentation"
      height : number = 360
        @label "Height"
        @description "Canvas height in pixels."
        @tier "presentation"
    }

    listens {
      LimitGate.LIMIT_GAME_END -> LIMIT_GAME_END
    }
  }

  page "/riya-limit" as RiyaLimitPage -> LimitMotion, LimitGate, LimitFx, RiyaLimitPlay
}


orbital RiyaExpoOrbital {
  uses Motion from "std/behaviors/std-motion-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"

  type RiyaExpoBody = {
    id : string!
    x : number!
    y : number!
    vx : number
    vy : number
    ax : number
    ay : number
  }
  type RiyaExpoFeature = {
    id : string
    x : number!
    y : number!
    z : number
    type : string!
    color : string
    elevation : number
    done : boolean
  }
  type RiyaExpoFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
  }

  entity RiyaExpoState [runtime, shared] {
    id : string!
    active : boolean = false
    bodies : [RiyaExpoBody] = []
    gravity : number = 0
    biasAx : number = 0
    biasAy : number = 0
    features : [RiyaExpoFeature] = []
    collected : [RiyaExpoFeature] = []
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaExpoFx] = []
    holding : number = 0
    celebrated : boolean = false
    ghostArmed : boolean = true
  }

  trait ExpoMotion = Motion.traits.MotionBody -> RiyaExpoState {
    events {
      THRUST: EXPO_THRUST
      IMPULSE: EXPO_IMPULSE
      PLACE: EXPO_PLACE
      SET_GRAVITY: EXPO_SET_GRAVITY
      RESTART: EXPO_RESTART
      BODY_MOVED: EXPO_MOVED
    }
    config {
      running: true
      gravity: 0
      damping: 0.94
      maxSpeed: 7
      xMin: -2.8
      xMax: 6.4
      yMin: -2
      yMax: 9
      bodies: [ { id: "hero", x: -2, y: 0, vx: 0, vy: 0, ax: 0, ay: 0 }, { id: "ghost", x: -2.8, y: 0, vx: 0, vy: 0, ax: 0, ay: 0 } ]
    }

    listens {
      THRUST { id : string!, ax : number!, ay : number! }
      IMPULSE { id : string!, dvx : number!, dvy : number! }
      PLACE { id : string!, x : number!, y : number! }
      SET_GRAVITY { gravity : number! }
      SET_BIAS { biasAx : number!, biasAy : number! }
      RESTART { id : string }
      RiyaExpoPlay.EXPO_IMPULSE -> EXPO_IMPULSE
      RiyaExpoPlay.EXPO_PLACE -> EXPO_PLACE
      RiyaExpoPlay.EXPO_RESTART -> EXPO_RESTART
      RiyaExpoPlay.EXPO_THRUST -> EXPO_THRUST
    }
  }

  trait ExpoGate = Gate.traits.ObjectiveFlow -> RiyaExpoState {
    events {
      PROGRESS: EXPO_PROGRESS
      GAME_END: EXPO_GAME_END
      RESTART: EXPO_RESTART
    }
    config { running: true }

    listens {
      PROGRESS { objectivesLeft : number, movesLeft : number }
      RESTART { id : string }
      RiyaExpoPlay.EXPO_PROGRESS -> EXPO_PROGRESS
      RiyaExpoPlay.EXPO_RESTART -> EXPO_RESTART
    }
  }

  trait ExpoFx = Particles.traits.FxParticles -> RiyaExpoState {
    events {
      BURST: EXPO_BURST
    }
    config { running: true }

    listens {
      BURST { particles : [Fx] }
      RESTART { }
      RiyaExpoPlay.EXPO_BURST -> EXPO_BURST
    }
  }

  trait RiyaExpoPlay -> @rebindable RiyaExpoState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.holding 0)
        (set @entity.celebrated false)
        (set @entity.features @config.stars)
        (set @entity.collected [])
        (set @entity.ghostArmed true)
        (set @entity.score 0)
        (set @entity.objectivesLeft (array/len @config.stars))
        (emit EXPO_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: "riya"
          hud: { type: game-hud, stats: [ { label: @config.objectiveText }, { label: "x", value: (math/round (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x) 1) }, { label: "f(x)", value: (math/round (- (math/pow 2 (* 0.5 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) 1) 1) }, { label: "2^n", value: (math/pow 2 @entity.score) }, { label: "★", value: @entity.score } ] }
          controls: { type: control-grid, kind: "dpad", directionEvents: { left: "EXPO_PAD_LEFT", right: "EXPO_PAD_RIGHT" } }
          overlay: (if (!= @entity.result "none") { type: game-menu, title: @config.clearTitle, subtitle: @config.clearSubtitle, options: [ { id: "next", label: "Next ▶", event: "EXPO_NEXT", variant: "primary" } ] } null)
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            keyMap: { ArrowLeft: "EXPO_PUSH_LEFT", KeyA: "EXPO_PUSH_LEFT", ArrowRight: "EXPO_PUSH_RIGHT", KeyD: "EXPO_PUSH_RIGHT" }
            keyUpMap: { ArrowLeft: "EXPO_PUSH_LEFT_UP", KeyA: "EXPO_PUSH_LEFT_UP", ArrowRight: "EXPO_PUSH_RIGHT_UP", KeyD: "EXPO_PUSH_RIGHT_UP" }
            curves: [ { label: "f(x) = 2^(x/2) − 1", color: "#94a3b8", samples: (array/map (array/range -28 65) (fn i (let ((xx (* @i 0.1))) { x: @xx, y: (- (math/pow 2 (* 0.5 @xx)) 1) }))) } ]
            points: (array/concat
              (array/map @entity.features (fn f { x: (object/get @f x), y: (object/get @f y), label: "★", color: @config.starColor, radius: 9 }))
              (array/concat
                [ { x: (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x), y: (- (math/pow 2 (* 0.5 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) 1), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  [ { x: (object/get (array/find @entity.bodies (fn b (== @b.id "ghost"))) x), y: (- (math/pow 2 (* 0.5 (object/get (array/find @entity.bodies (fn b (== @b.id "ghost"))) x))) 1), label: "2^n", color: @config.ghostColor, radius: 7 } ]
                  (array/map @entity.fx (fn e { x: (object/get @e x), y: (+ (object/get @e z) 0.6), label: (object/get @e message), color: "#ffe066", radius: 4 })))))
            vectors: [ { x: (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x), y: (- (math/pow 2 (* 0.5 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) 1), vx: (* (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) vx) 0.3), vy: 0, color: @config.riyaColor, label: "v" } ]
          } ]
        })

      EXPO_PUSH_LEFT -> idle when (and (== @entity.active true) (and (== @entity.result "none") (!= @entity.holding -1)))
        (set @entity.holding -1)
        (emit EXPO_THRUST { id: "hero", ax: (- 0 @config.thrust), ay: 0 })

      EXPO_PUSH_RIGHT -> idle when (and (== @entity.active true) (and (== @entity.result "none") (!= @entity.holding 1)))
        (set @entity.holding 1)
        (emit EXPO_THRUST { id: "hero", ax: @config.thrust, ay: 0 })

      EXPO_PUSH_LEFT_UP -> idle when (== @entity.holding -1)
        (set @entity.holding 0)
        (emit EXPO_THRUST { id: "hero", ax: 0, ay: 0 })

      EXPO_PUSH_RIGHT_UP -> idle when (== @entity.holding 1)
        (set @entity.holding 0)
        (emit EXPO_THRUST { id: "hero", ax: 0, ay: 0 })

      EXPO_PAD_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit EXPO_IMPULSE { id: "hero", dvx: (- 0 @config.padImpulse), dvy: 0 })

      EXPO_PAD_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit EXPO_IMPULSE { id: "hero", dvx: @config.padImpulse, dvy: 0 })

      EXPO_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "expo" })

      EXPO_NEXT -> idle
        (navigate @config.nextPath)
    }

    ticks {
      gameTick every 50ms when (and (== @entity.active true) (and (== @entity.result "none") (> (array/len @entity.bodies) 0)))
        (let ((hx (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x)))
        (let ((gx (object/get (array/find @entity.bodies (fn b (== @b.id "ghost"))) x)))
        (do
          (let ((matched (array/filter @entity.features (fn f (<= (grid/manhattan-distance { x: (object/get @f x), y: (object/get @f y) } { x: @hx, y: (- (math/pow 2 (* 0.5 @hx)) 1) }) @config.reachRadius)))))
          (if (> (array/len @matched) 0)
            (do
              (set @entity.features (array/filter @entity.features (fn f (> (grid/manhattan-distance { x: (object/get @f x), y: (object/get @f y) } { x: @hx, y: (- (math/pow 2 (* 0.5 @hx)) 1) }) @config.reachRadius))))
              (set @entity.collected (array/concat @entity.collected @matched))
              (set @entity.score (+ @entity.score (array/len @matched)))
              (set @entity.objectivesLeft (- @entity.objectivesLeft (array/len @matched)))
              (emit EXPO_BURST { particles: (array/map @matched (fn f { id: (str/concat "fx-expo-" (object/get @f id)), type: "pickup", x: (object/get @f x), z: (object/get @f y), message: "+1", ttl: 3 })) })
              (emit EXPO_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 }))
            null))
          (emit EXPO_THRUST { id: "ghost", ax: (* (math/sign (- @hx @gx)) (* @config.ghostThrust (math/pow 2 @entity.score))), ay: 0 })
          (if (and (== @entity.ghostArmed false) (> (grid/manhattan-distance { x: @gx, y: (- (math/pow 2 (* 0.5 @gx)) 1) } { x: @hx, y: (- (math/pow 2 (* 0.5 @hx)) 1) }) @config.rearmDistance))
            (set @entity.ghostArmed true)
            null)
          (if (and (== @entity.ghostArmed true) (<= (grid/manhattan-distance { x: @gx, y: (- (math/pow 2 (* 0.5 @gx)) 1) } { x: @hx, y: (- (math/pow 2 (* 0.5 @hx)) 1) }) @config.catchRadius))
            (do
              (set @entity.ghostArmed false)
              (if (> (array/len @entity.collected) 0)
                (do
                  (set @entity.features (array/concat @entity.features [ (array/last @entity.collected) ]))
                  (set @entity.collected (array/filter @entity.collected (fn f (!= @f.id (object/get (array/last @entity.collected) id)))))
                  (set @entity.score (- @entity.score 1))
                  (set @entity.objectivesLeft (+ @entity.objectivesLeft 1))
                  (emit EXPO_BURST { particles: [ { id: "fx-expo-catch", type: "hit", x: @hx, z: (- (math/pow 2 (* 0.5 @hx)) 1), message: "-1 ★", ttl: 3 } ] }))
                null)
              (emit EXPO_PLACE { id: "ghost", x: @config.ghostSpawnX, y: 0 }))
            null))))

      renderTick every 100ms when (and (== @entity.active true) (> (array/len @entity.bodies) 0))
        (render-ui main {
          type: game-shell
          appName: "riya"
          hud: { type: game-hud, stats: [ { label: @config.objectiveText }, { label: "x", value: (math/round (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x) 1) }, { label: "f(x)", value: (math/round (- (math/pow 2 (* 0.5 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) 1) 1) }, { label: "2^n", value: (math/pow 2 @entity.score) }, { label: "★", value: @entity.score } ] }
          controls: { type: control-grid, kind: "dpad", directionEvents: { left: "EXPO_PAD_LEFT", right: "EXPO_PAD_RIGHT" } }
          overlay: (if (!= @entity.result "none") { type: game-menu, title: @config.clearTitle, subtitle: @config.clearSubtitle, options: [ { id: "next", label: "Next ▶", event: "EXPO_NEXT", variant: "primary" } ] } null)
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            keyMap: { ArrowLeft: "EXPO_PUSH_LEFT", KeyA: "EXPO_PUSH_LEFT", ArrowRight: "EXPO_PUSH_RIGHT", KeyD: "EXPO_PUSH_RIGHT" }
            keyUpMap: { ArrowLeft: "EXPO_PUSH_LEFT_UP", KeyA: "EXPO_PUSH_LEFT_UP", ArrowRight: "EXPO_PUSH_RIGHT_UP", KeyD: "EXPO_PUSH_RIGHT_UP" }
            curves: [ { label: "f(x) = 2^(x/2) − 1", color: "#94a3b8", samples: (array/map (array/range -28 65) (fn i (let ((xx (* @i 0.1))) { x: @xx, y: (- (math/pow 2 (* 0.5 @xx)) 1) }))) } ]
            points: (array/concat
              (array/map @entity.features (fn f { x: (object/get @f x), y: (object/get @f y), label: "★", color: @config.starColor, radius: 9 }))
              (array/concat
                [ { x: (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x), y: (- (math/pow 2 (* 0.5 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) 1), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  [ { x: (object/get (array/find @entity.bodies (fn b (== @b.id "ghost"))) x), y: (- (math/pow 2 (* 0.5 (object/get (array/find @entity.bodies (fn b (== @b.id "ghost"))) x))) 1), label: "2^n", color: @config.ghostColor, radius: 7 } ]
                  (array/map @entity.fx (fn e { x: (object/get @e x), y: (+ (object/get @e z) 0.6), label: (object/get @e message), color: "#ffe066", radius: 4 })))))
            vectors: [ { x: (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x), y: (- (math/pow 2 (* 0.5 (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) x))) 1), vx: (* (object/get (array/find @entity.bodies (fn b (== @b.id "hero"))) vx) 0.3), vy: 0, color: @config.riyaColor, label: "v" } ]
          } ]
        })
    }


    emits {
      EXPO_PUSH_LEFT -> external {
        id : string
      }
        @description "Hold-to-push intent from ArrowLeft/KeyA keydown (math-canvas keyMap); guarded on holding-change so OS key-repeat can't re-fire the THRUST emit."
        @tier "domain"
      EXPO_PUSH_RIGHT -> external {
        id : string
      }
        @description "Hold-to-push intent from ArrowRight/KeyD keydown (math-canvas keyMap); guarded on holding-change so OS key-repeat can't re-fire the THRUST emit."
        @tier "domain"
      EXPO_PUSH_LEFT_UP -> external {
        id : string
      }
        @description "ArrowLeft/KeyA keyup (math-canvas keyUpMap); releases the push so damping coasts riya to a stop."
        @tier "domain"
      EXPO_PUSH_RIGHT_UP -> external {
        id : string
      }
        @description "ArrowRight/KeyD keyup (math-canvas keyUpMap); releases the push so damping coasts riya to a stop."
        @tier "domain"
      EXPO_PAD_LEFT -> external {
        id : string
      }
        @description "D-pad left tap (control-grid directionEvents); applied as an instant velocity kick via EXPO_IMPULSE."
        @tier "domain"
      EXPO_PAD_RIGHT -> external {
        id : string
      }
        @description "D-pad right tap (control-grid directionEvents); applied as an instant velocity kick via EXPO_IMPULSE."
        @tier "domain"
      EXPO_RESTART -> external {
        id : string
      }
        @description "Reseed broadcast consumed by this world's motion-body/objective-flow authorities (renamed RESTART)."
        @tier "domain"
      EXPO_THRUST -> external {
        id : string!
        ax : number!
        ay : number!
      }
        @description "Acceleration intent applied by this world's motion-body authority (renamed THRUST); sparse — fired only on keydown/keyup transitions, never per tick."
        @tier "domain"
      EXPO_IMPULSE -> external {
        id : string!
        dvx : number!
        dvy : number!
      }
        @description "Instant velocity kick applied by this world's motion-body authority (renamed IMPULSE); the d-pad's push."
        @tier "domain"
      EXPO_PLACE -> external {
        id : string!
        x : number!
        y : number!
      }
        @description "Teleport intent applied by this world's motion-body authority (renamed PLACE); the gameTick sends the ghost back to its spawn after a catch (sparse — only on a catch)."
        @tier "domain"
      EXPO_BURST -> external {
        particles : [RiyaExpoFx]
      }
        @description "Pickup particle batch spawned by the gameTick when a star is collected (sparse — only on a catch); fx-particles fades it."
        @tier "domain"
      EXPO_PROGRESS -> external {
        objectivesLeft : number!
        movesLeft : number!
      }
        @description "Sparse progress signal emitted by the gameTick only when a star is collected; the objective-flow gate resolves won from it."
        @tier "domain"
      EXPO_GAME_END -> external {
        result : string!
      }
        @description "Win-gate resolution from this world's objective-flow authority (renamed GAME_END); won clears the level."
        @tier "domain"
      RIYA_LEVEL_SOLVED -> external {
        level : string
      }
        @description "Every ★ captured — the win gate resolved won (guarded by celebrated so the gate's repeated GAME_ENDs fire it once)."
        @tier "domain"
      EXPO_NEXT -> external {
        id : string
      }
        @description "Clear-overlay Next button; navigates to the next world's page."
        @tier "domain"
    }

    config {
      stars : [RiyaExpoFeature] = [ { id: "s1", x: 0, y: 0, type: "star" }, { id: "s2", x: 2, y: 1, type: "star" }, { id: "s3", x: 4, y: 3, type: "star" }, { id: "s4", x: 6, y: 7, type: "star" } ]
        @label "Stars"
        @description "Collectible star positions — exact points of 2^(x/2) − 1 at heights 0, 1, 3, 7, one short of the powers of two 1, 2, 4, 8."
        @tier "domain"
      thrust : number = 14
        @label "Thrust"
        @description "Acceleration in world units/s² applied while a direction key is held."
        @tier "domain"
      padImpulse : number = 2.5
